@Test
public void testCreateInvalidTopology() {
    List<NodeSchema> schemas = new ArrayList<NodeSchema>();
    schemas.add(ROOT_SCHEMA);
    schemas.add(RACK_SCHEMA);
    schemas.add(LEAF_SCHEMA);
    NodeSchemaManager.getInstance().init(schemas.toArray(new NodeSchema[0]), true);
    NetworkTopology newCluster = new NetworkTopologyImpl(NodeSchemaManager.getInstance());
    Node[] invalidDataNodes = new Node[] { createDatanode("1.1.1.1", "/r1"), createDatanode("2.2.2.2", "/r2"), createDatanode("3.3.3.3", "/d1/r2") };
