@Test
public void testChooseRandomWithAffinityNode() {
    int[] excludedNodeIndexs = { 0, dataNodes.length - 1, random.nextInt(dataNodes.length), random.nextInt(dataNodes.length) };
    Node[][] excludedNodeLists = { {}, { dataNodes[0] }, { dataNodes[dataNodes.length - 1] }, { dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] } };
    int[] affinityNodeIndexs = { 0, dataNodes.length - 1, random.nextInt(dataNodes.length), random.nextInt(dataNodes.length) };
    Node[][] excludedScopeIndexs = { { dataNodes[0] }, { dataNodes[dataNodes.length - 1] }, { dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] } };
    int leafNum = cluster.getNumOfLeafNode(null);
    Map<Node, Integer> frequency;
    List<String> pathList = new ArrayList<>();
    for (int k : affinityNodeIndexs) {
        for (Node[] excludedScopes : excludedScopeIndexs) {
            pathList.clear();
            pathList.addAll(Arrays.stream(excludedScopes).map(node -> node.getNetworkFullPath()).collect(Collectors.toList()));
            while (!pathList.get(0).equals(ROOT)) {
                int ancestorGen = cluster.getMaxLevel() - 1;
                while (ancestorGen > 0) {
                    for (Node[] list : excludedNodeLists) {
                        List<Node> excludedList = Arrays.asList(list);
                        frequency = pickNodes(leafNum, pathList, excludedList, dataNodes[k], ancestorGen);
                        Node affinityAncestor = dataNodes[k].getAncestor(ancestorGen);
                        for (Node key : dataNodes) {
                            if (affinityAncestor != null) {
                                if (frequency.get(key) > 0) {
                                    assertTrue(affinityAncestor.isAncestor(key));
                                } else if (!affinityAncestor.isAncestor(key)) {
                                    continue;
                                } else if (excludedList != null && excludedList.contains(key)) {
                                    continue;
                                } else if (pathList != null && pathList.stream().anyMatch(path -> key.getNetworkFullPath().startsWith(path))) {
                                    continue;
                                } else {
                                    fail("Node is not picked when sequentially going " + "through ancestor node's leaf nodes. node:" + key.getNetworkFullPath() + ", ancestor node:" + affinityAncestor.getNetworkFullPath() + ", excludedScope: " + pathList.toString() + ", " + "excludedList:" + (excludedList == null ? "" : excludedList.toString()));
                                }
                            }
                        }
                    }
                    ancestorGen--;
                }
                pathList = pathList.stream().map(path -> path.substring(0, path.lastIndexOf(PATH_SEPARATOR_STR))).collect(Collectors.toList());
            }
        }
    }
    // all nodes excluded, no node will be picked
    String scope;
    List<Node> excludedList = Arrays.asList(dataNodes);
    for (int k : affinityNodeIndexs) {
        for (int i : excludedNodeIndexs) {
            String path = dataNodes[i].getNetworkFullPath();
            while (!path.equals(ROOT)) {
                scope = "~" + path;
                int ancestorGen = 0;
                while (ancestorGen < cluster.getMaxLevel()) {
                    frequency = pickNodesAtRandom(leafNum, scope, excludedList, dataNodes[k], ancestorGen);
                    for (Node key : dataNodes) {
                        assertTrue(frequency.get(key) == 0);
                    }
                    ancestorGen++;
                }
                path = path.substring(0, path.lastIndexOf(PATH_SEPARATOR_STR));
            }
        }
    }
    // no node excluded and no excluded scope, each node will be picked
    int ancestorGen = cluster.getMaxLevel() - 1;
    for (int k : affinityNodeIndexs) {
        while (ancestorGen > 0) {
            frequency = pickNodes(leafNum, null, null, dataNodes[k], ancestorGen);
            Node affinityAncestor = dataNodes[k].getAncestor(ancestorGen);
            for (Node key : dataNodes) {
                if (frequency.get(key) > 0) {
                    if (affinityAncestor != null) {
                        assertTrue(affinityAncestor.isAncestor(key));
                    }
                }
            }
            ancestorGen--;
        }
    }
    // check invalid ancestor generation
    try {
        cluster.chooseRandom(null, null, null, dataNodes[0], cluster.getMaxLevel());
        fail("ancestor generation exceeds max level, should fail");
    } catch (Exception e) {
        assertTrue(e.getMessage().startsWith("ancestorGen " + cluster.getMaxLevel() + " exceeds this network topology acceptable level"));
    }
}

