@Test
public void testSortByDistanceCost() {
    Node[][] nodes = { {}, { dataNodes[0] }, { dataNodes[dataNodes.length - 1] }, { dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] }, { dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] } };
    Node[] readers = { null, dataNodes[0], dataNodes[dataNodes.length - 1], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)], dataNodes[random.nextInt(dataNodes.length)] };
    for (Node reader : readers) {
        for (Node[] nodeList : nodes) {
            int length = nodeList.length;
            while (length > 0) {
                List<? extends Node> ret = cluster.sortByDistanceCost(reader, Arrays.asList(nodeList), length);
                for (int i = 0; i < ret.size(); i++) {
                    if ((i + 1) < ret.size()) {
                        int cost1 = cluster.getDistanceCost(reader, ret.get(i));
                        int cost2 = cluster.getDistanceCost(reader, ret.get(i + 1));
                        assertTrue("reader:" + (reader != null ? reader.getNetworkFullPath() : "null") + ",node1:" + ret.get(i).getNetworkFullPath() + ",node2:" + ret.get(i + 1).getNetworkFullPath() + ",cost1:" + cost1 + ",cost2:" + cost2, cost1 == Integer.MAX_VALUE || cost1 <= cost2);
                    }
                }
                length--;
            }
        }
    }
    // sort all nodes
    List<Node> nodeList = Arrays.asList(dataNodes.clone());
    for (Node reader : readers) {
        int length = nodeList.size();
        while (length >= 0) {
            List<? extends Node> sortedNodeList = cluster.sortByDistanceCost(reader, nodeList, length);
            for (int i = 0; i < sortedNodeList.size(); i++) {
                if ((i + 1) < sortedNodeList.size()) {
                    int cost1 = cluster.getDistanceCost(reader, sortedNodeList.get(i));
                    int cost2 = cluster.getDistanceCost(reader, sortedNodeList.get(i + 1));
                    // node can be removed when called in testConcurrentAccess
                    assertTrue("reader:" + (reader != null ? reader.getNetworkFullPath() : "null") + ",node1:" + sortedNodeList.get(i).getNetworkFullPath() + ",node2:" + sortedNodeList.get(i + 1).getNetworkFullPath() + ",cost1:" + cost1 + ",cost2:" + cost2, cost1 == Integer.MAX_VALUE || cost1 <= cost2);
                }
            }
            length--;
        }
    }
}

