    OzoneBlockTokenIdentifier tokenId = new OzoneBlockTokenIdentifier("testUser", "84940", EnumSet.allOf(HddsProtos.BlockTokenSecretProto.AccessModeProto.class), expiryTime, cert.getSerialNumber().toString(), maxLength);
    byte[] signedToken = signTokenAsymmetric(tokenId, privateKey);
    Token<OzoneBlockTokenIdentifier> token = new Token(tokenId.getBytes(), signedToken, tokenId.getKind(), new Text("host:port"));
    String encodeToUrlString = token.encodeToUrlString();
    Token<OzoneBlockTokenIdentifier> decodedToken = new Token();
    decodedToken.decodeFromUrlString(encodeToUrlString);
    OzoneBlockTokenIdentifier decodedTokenId = new OzoneBlockTokenIdentifier();
    decodedTokenId.readFields(new DataInputStream(new ByteArrayInputStream(decodedToken.getIdentifier())));
    Assert.assertEquals(decodedTokenId, tokenId);
    Assert.assertEquals(decodedTokenId.getMaxLength(), maxLength);
    // Verify a decoded signed Token with public key(certificate)
    boolean isValidToken = verifyTokenAsymmetric(decodedTokenId, decodedToken.getPassword(), cert);
    LOG.info("{} is {}", tokenId, isValidToken ? "valid." : "invalid.");
}

@Test
public void testAsymmetricTokenPerf() throws NoSuchAlgorithmException, CertificateEncodingException, NoSuchProviderException, InvalidKeyException, SignatureException {
    final int testTokenCount = 1000;
    List<OzoneBlockTokenIdentifier> tokenIds = new ArrayList<>();
    List<byte[]> tokenPasswordAsym = new ArrayList<>();
    for (int i = 0; i < testTokenCount; i++) {
        tokenIds.add(generateTestToken());
    }
    KeyPair kp = KeyStoreTestUtil.generateKeyPair("RSA");
    // Create Ozone Master certificate (SCM CA issued cert) and key store
    X509Certificate certificate;
    certificate = KeyStoreTestUtil.generateCertificate("CN=OzoneMaster", kp, 30, "SHA256withRSA");
    long startTime = Time.monotonicNowNanos();
    for (int i = 0; i < testTokenCount; i++) {
        tokenPasswordAsym.add(signTokenAsymmetric(tokenIds.get(i), kp.getPrivate()));
    }
    long duration = Time.monotonicNowNanos() - startTime;
    LOG.info("Average token sign time with HmacSha256(RSA/1024 key) is {} ns", duration / testTokenCount);
    startTime = Time.monotonicNowNanos();
    for (int i = 0; i < testTokenCount; i++) {
        verifyTokenAsymmetric(tokenIds.get(i), tokenPasswordAsym.get(i), certificate);
    }
    duration = Time.monotonicNowNanos() - startTime;
    LOG.info("Average token verify time with HmacSha256(RSA/1024 key) " + "is {} ns", duration / testTokenCount);
}

