@Test
public void testPartialTableCache() {
    for (int i = 0; i < 10; i++) {
        tableCache.put(new CacheKey<>(Integer.toString(i)), new CacheValue<>(Optional.of(Integer.toString(i)), i));
    }
    for (int i = 0; i < 10; i++) {
        Assert.assertEquals(Integer.toString(i), tableCache.get(new CacheKey<>(Integer.toString(i))).getCacheValue());
    }
    ArrayList<Long> epochs = new ArrayList();
    epochs.add(0L);
    epochs.add(1L);
    epochs.add(2L);
    epochs.add(3L);
    epochs.add(4L);
    // On a full table cache if some one calls cleanup it is a no-op.
    tableCache.evictCache(epochs);
