@Test
public void testContainerImportExport() throws Exception {
    long containerId = keyValueContainer.getContainerData().getContainerID();
    // Create Container.
    keyValueContainer.create(volumeSet, volumeChoosingPolicy, scmId);
    keyValueContainerData = keyValueContainer.getContainerData();
    keyValueContainerData.setState(ContainerProtos.ContainerDataProto.State.CLOSED);
    int numberOfKeysToWrite = 12;
    //write one few keys to check the key count after import
    try (ReferenceCountedDB metadataStore = BlockUtils.getDB(keyValueContainerData, conf)) {
        for (int i = 0; i < numberOfKeysToWrite; i++) {
            metadataStore.getStore().put(("test" + i).getBytes(UTF_8), "test".getBytes(UTF_8));
        }
    }
    BlockUtils.removeDB(keyValueContainerData, conf);
    Map<String, String> metadata = new HashMap<>();
    metadata.put("key1", "value1");
    keyValueContainer.update(metadata, true);
    //destination path
    File folderToExport = folder.newFile("exported.tar.gz");
    TarContainerPacker packer = new TarContainerPacker();
    //export the container
    try (FileOutputStream fos = new FileOutputStream(folderToExport)) {
        keyValueContainer.exportContainerData(fos, packer);
    }
    //delete the original one
    keyValueContainer.delete();
    //create a new one
    KeyValueContainerData containerData = new KeyValueContainerData(containerId, 1, keyValueContainerData.getMaxSize(), UUID.randomUUID().toString(), datanodeId.toString());
    KeyValueContainer container = new KeyValueContainer(containerData, conf);
    HddsVolume containerVolume = volumeChoosingPolicy.chooseVolume(volumeSet.getVolumesList(), 1);
    String hddsVolumeDir = containerVolume.getHddsRootDir().toString();
    container.populatePathFields(scmId, containerVolume, hddsVolumeDir);
    try (FileInputStream fis = new FileInputStream(folderToExport)) {
        container.importContainerData(fis, packer);
    }
    assertEquals("value1", containerData.getMetadata().get("key1"));
    assertEquals(keyValueContainerData.getContainerDBType(), containerData.getContainerDBType());
    assertEquals(keyValueContainerData.getState(), containerData.getState());
    assertEquals(numberOfKeysToWrite, containerData.getKeyCount());
    assertEquals(keyValueContainerData.getLayOutVersion(), containerData.getLayOutVersion());
    assertEquals(keyValueContainerData.getMaxSize(), containerData.getMaxSize());
    assertEquals(keyValueContainerData.getBytesUsed(), containerData.getBytesUsed());
    //Can't overwrite existing container
    try {
        try (FileInputStream fis = new FileInputStream(folderToExport)) {
            container.importContainerData(fis, packer);
        }
        fail("Container is imported twice. Previous files are overwritten");
    } catch (IOException ex) {
        //all good
    }
}

