/**
 * Sanity test, when there are corruptions induced.
 */
@Test
public void testKeyValueContainerCheckCorruption() throws Exception {
    long containerID = 102;
    int deletedBlocks = 1;
    int normalBlocks = 3;
    int chunksPerBlock = 4;
    ContainerScrubberConfiguration sc = conf.getObject(ContainerScrubberConfiguration.class);
    // test Closed Container
    createContainerWithBlocks(containerID, normalBlocks, deletedBlocks, chunksPerBlock);
    container.close();
    KeyValueContainerCheck kvCheck = new KeyValueContainerCheck(containerData.getMetadataPath(), conf, containerID);
    File metaDir = new File(containerData.getMetadataPath());
    File dbFile = KeyValueContainerLocationUtil.getContainerDBFile(metaDir, containerID);
    containerData.setDbFile(dbFile);
    try (ReferenceCountedDB ignored = BlockUtils.getDB(containerData, conf);
        KeyValueBlockIterator kvIter = new KeyValueBlockIterator(containerID, new File(containerData.getContainerPath()))) {
        BlockData block = kvIter.nextBlock();
        assertFalse(block.getChunks().isEmpty());
        ContainerProtos.ChunkInfo c = block.getChunks().get(0);
        File chunkFile = ChunkUtils.getChunkFile(containerData, ChunkInfo.getFromProtoBuf(c));
        long length = chunkFile.length();
        assertTrue(length > 0);
        // forcefully truncate the file to induce failure.
        try (RandomAccessFile file = new RandomAccessFile(chunkFile, "rws")) {
            file.setLength(length / 2);
        }
        assertEquals(length / 2, chunkFile.length());
    }
    // metadata check should pass.
    boolean valid = kvCheck.fastCheck();
    assertTrue(valid);
    // checksum validation should fail.
    valid = kvCheck.fullCheck(new DataTransferThrottler(sc.getBandwidthPerVolume()), null);
    assertFalse(valid);
}

