@Test
public void pack() throws IOException, CompressorException {
    //GIVEN
    OzoneConfiguration conf = new OzoneConfiguration();
    KeyValueContainerData sourceContainerData = createContainer(SOURCE_CONTAINER_ROOT);
    KeyValueContainer sourceContainer = new KeyValueContainer(sourceContainerData, conf);
    //sample db file in the metadata directory
    writeDbFile(sourceContainerData, TEST_DB_FILE_NAME);
    //sample chunk file in the chunk directory
    writeChunkFile(sourceContainerData, TEST_CHUNK_FILE_NAME);
    //sample container descriptor file
    writeDescriptor(sourceContainer);
    Path targetFile = TEMP_DIR.resolve("container.tar.gz");
    //WHEN: pack it
    try (FileOutputStream output = new FileOutputStream(targetFile.toFile())) {
        packer.pack(sourceContainer, output);
    }
    //THEN: check the result
    try (FileInputStream input = new FileInputStream(targetFile.toFile())) {
        CompressorInputStream uncompressed = new CompressorStreamFactory().createCompressorInputStream(GZIP, input);
        TarArchiveInputStream tarStream = new TarArchiveInputStream(uncompressed);
        TarArchiveEntry entry;
        Map<String, TarArchiveEntry> entries = new HashMap<>();
        while ((entry = tarStream.getNextTarEntry()) != null) {
            entries.put(entry.getName(), entry);
        }
        Assert.assertTrue(entries.containsKey("container.yaml"));
    }
    //read the container descriptor only
    try (FileInputStream input = new FileInputStream(targetFile.toFile())) {
        String containerYaml = new String(packer.unpackContainerDescriptor(input), Charset.forName(UTF_8.name()));
        Assert.assertEquals(TEST_DESCRIPTOR_FILE_CONTENT, containerYaml);
    }
    KeyValueContainerData destinationContainerData = createContainer(DEST_CONTAINER_ROOT);
    KeyValueContainer destinationContainer = new KeyValueContainer(destinationContainerData, conf);
    String descriptor;
    //unpackContainerData
    try (FileInputStream input = new FileInputStream(targetFile.toFile())) {
        descriptor = new String(packer.unpackContainerData(destinationContainer, input), Charset.forName(UTF_8.name()));
    }
    assertExampleMetadataDbIsGood(destinationContainerData.getDbFile().toPath(), TEST_DB_FILE_NAME);
    assertExampleChunkFileIsGood(Paths.get(destinationContainerData.getChunksPath()), TEST_CHUNK_FILE_NAME);
    Assert.assertFalse("Descriptor file should not have been extracted by the " + "unpackContainerData Call", destinationContainer.getContainerFile().exists());
    Assert.assertEquals(TEST_DESCRIPTOR_FILE_CONTENT, descriptor);
}

