@Test
public void testAllocateBlockInParallel() throws Exception {
    eventQueue.fireEvent(SCMEvents.SAFE_MODE_STATUS, safeModeStatus);
    GenericTestUtils.waitFor(() -> {
        return !blockManager.isScmInSafeMode();
    }, 10, 1000 * 5);
    int threadCount = 20;
    List<ExecutorService> executors = new ArrayList<>(threadCount);
    for (int i = 0; i < threadCount; i++) {
        executors.add(Executors.newSingleThreadExecutor());
    }
    List<CompletableFuture<AllocatedBlock>> futureList = new ArrayList<>(threadCount);
    for (int i = 0; i < threadCount; i++) {
        final CompletableFuture<AllocatedBlock> future = new CompletableFuture<>();
        CompletableFuture.supplyAsync(() -> {
            try {
                future.complete(blockManager.allocateBlock(DEFAULT_BLOCK_SIZE, type, factor, OzoneConsts.OZONE, new ExcludeList()));
            } catch (IOException e) {
                future.completeExceptionally(e);
            }
            return future;
        }, executors.get(i));
        futureList.add(future);
    }
    try {
        CompletableFuture.allOf(futureList.toArray(new CompletableFuture[futureList.size()])).get();
    } catch (Exception e) {
        Assert.fail("testAllocateBlockInParallel failed");
    }
}

