    when(nodeManager.getNodeStat(datanodes.get(2))).thenReturn(new SCMNodeMetric(storageCapacity, 90L, 10L));
    when(nodeManager.getNodeStat(datanodes.get(3))).thenReturn(new SCMNodeMetric(storageCapacity, 80L, 20L));
    when(nodeManager.getNodeStat(datanodes.get(4))).thenReturn(new SCMNodeMetric(storageCapacity, 70L, 30L));
    ContainerPlacementPolicy policy = ContainerPlacementPolicyFactory.getPolicy(conf, nodeManager, cluster, true, SCMContainerPlacementMetrics.create());
    int nodeNum = 3;
    List<DatanodeDetails> datanodeDetails = policy.chooseDatanodes(null, null, nodeNum, 15);
