public void testAllocateContainerInParallel() throws Exception {
    int threadCount = 20;
    List<ExecutorService> executors = new ArrayList<>(threadCount);
    for (int i = 0; i < threadCount; i++) {
        executors.add(Executors.newSingleThreadExecutor());
    }
    List<CompletableFuture<ContainerInfo>> futureList = new ArrayList<>(threadCount);
    for (int i = 0; i < threadCount; i++) {
        final CompletableFuture<ContainerInfo> future = new CompletableFuture<>();
        CompletableFuture.supplyAsync(() -> {
            try {
                ContainerInfo containerInfo = containerManager.allocateContainer(replicationType, replicationFactor, OzoneConsts.OZONE);
                Assert.assertNotNull(containerInfo);
                Assert.assertNotNull(containerInfo.getPipelineID());
                future.complete(containerInfo);
                return containerInfo;
            } catch (IOException e) {
                future.completeExceptionally(e);
            }
            return future;
        }, executors.get(i));
        futureList.add(future);
    }
    try {
        CompletableFuture.allOf(futureList.toArray(new CompletableFuture[futureList.size()])).get();
    } catch (Exception e) {
        Assert.fail("testAllocateBlockInParallel failed");
    }
}

