@Test
public void testGetContainerWithPipeline() throws Exception {
    ContainerInfo contInfo = containerManager.allocateContainer(replicationType, replicationFactor, OzoneConsts.OZONE);
    // Add dummy replicas for container.
    Iterator<DatanodeDetails> nodes = pipelineManager.getPipeline(contInfo.getPipelineID()).getNodes().iterator();
    DatanodeDetails dn1 = nodes.next();
    containerManager.updateContainerState(contInfo.containerID(), LifeCycleEvent.FINALIZE);
    containerManager.updateContainerState(contInfo.containerID(), LifeCycleEvent.CLOSE);
    ContainerInfo finalContInfo = contInfo;
    Assert.assertEquals(0, containerManager.getContainerReplicas(finalContInfo.containerID()).size());
    containerManager.updateContainerReplica(contInfo.containerID(), ContainerReplica.newBuilder().setContainerID(contInfo.containerID()).setContainerState(ContainerReplicaProto.State.CLOSED).setDatanodeDetails(dn1).build());
    Assert.assertEquals(1, containerManager.getContainerReplicas(finalContInfo.containerID()).size());
    contInfo = containerManager.getContainer(contInfo.containerID());
    Assert.assertEquals(LifeCycleState.CLOSED, contInfo.getState());
    // After closing the container, we should get the replica and construct
    // standalone pipeline. No more ratis pipeline.
    Set<DatanodeDetails> replicaNodes = containerManager.getContainerReplicas(contInfo.containerID()).stream().map(ContainerReplica::getDatanodeDetails).collect(Collectors.toSet());
    Assert.assertTrue(replicaNodes.contains(dn1));
}

@Test
public void testGetContainerReplicaWithParallelUpdate() throws Exception {
    testGetContainerWithPipeline();
    final Optional<ContainerID> id = containerManager.getContainerIDs().stream().findFirst();
    Assert.assertTrue(id.isPresent());
    final ContainerID cId = id.get();
    final Optional<ContainerReplica> replica = containerManager.getContainerReplicas(cId).stream().findFirst();
    Assert.assertTrue(replica.isPresent());
    final ContainerReplica cReplica = replica.get();
    final AtomicBoolean runUpdaterThread = new AtomicBoolean(true);
    Thread updaterThread = new Thread(() -> {
        while (runUpdaterThread.get()) {
            try {
                containerManager.removeContainerReplica(cId, cReplica);
                containerManager.updateContainerReplica(cId, cReplica);
            } catch (ContainerException e) {
                Assert.fail("Container Exception: " + e.getMessage());
            }
        }
    });
    updaterThread.setDaemon(true);
    updaterThread.start();
    IntStream.range(0, 100).forEach(i -> {
        try {
            Assert.assertNotNull(containerManager.getContainerReplicas(cId).stream().map(ContainerReplica::getDatanodeDetails).collect(Collectors.toSet()));
        } catch (ContainerNotFoundException e) {
            Assert.fail("Missing Container " + id);
        }
    });
    runUpdaterThread.set(false);
}

