@Test
public void testPipelineReport() throws IOException {
    EventQueue eventQueue = new EventQueue();
    SCMPipelineManager pipelineManager = new SCMPipelineManager(conf, nodeManager, eventQueue);
    PipelineProvider mockRatisProvider = new MockRatisPipelineProvider(nodeManager, pipelineManager.getStateManager(), conf);
    pipelineManager.setPipelineProvider(HddsProtos.ReplicationType.RATIS, mockRatisProvider);
    SCMSafeModeManager scmSafeModeManager = new SCMSafeModeManager(conf, new ArrayList<>(), pipelineManager, eventQueue);
    // create a pipeline in allocated state with no dns yet reported
    Pipeline pipeline = pipelineManager.createPipeline(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE);
    Assert.assertFalse(pipelineManager.getPipeline(pipeline.getId()).isHealthy());
    Assert.assertFalse(pipelineManager.getPipeline(pipeline.getId()).isOpen());
    // pipeline is not healthy until all dns report
    List<DatanodeDetails> nodes = pipeline.getNodes();
    Assert.assertFalse(pipelineManager.getPipeline(pipeline.getId()).isHealthy());
    // get pipeline report from each dn in the pipeline
    PipelineReportHandler pipelineReportHandler = new PipelineReportHandler(scmSafeModeManager, pipelineManager, conf);
    nodes.subList(0, 2).forEach(dn -> sendPipelineReport(dn, pipeline, pipelineReportHandler, false, eventQueue));
    sendPipelineReport(nodes.get(nodes.size() - 1), pipeline, pipelineReportHandler, true, eventQueue);
    // pipeline is healthy when all dns report
    Assert.assertTrue(pipelineManager.getPipeline(pipeline.getId()).isHealthy());
    // pipeline should now move to open state
    Assert.assertTrue(pipelineManager.getPipeline(pipeline.getId()).isOpen());
    // close the pipeline
    pipelineManager.finalizeAndDestroyPipeline(pipeline, false);
    // pipeline report for destroyed pipeline should be ignored
    nodes.subList(0, 2).forEach(dn -> sendPipelineReport(dn, pipeline, pipelineReportHandler, false, eventQueue));
    sendPipelineReport(nodes.get(nodes.size() - 1), pipeline, pipelineReportHandler, true, eventQueue);
    try {
        pipelineManager.getPipeline(pipeline.getId());
        Assert.fail("Pipeline should not have been retrieved");
    } catch (IOException e) {
        Assert.assertTrue(e.getMessage().contains("not found"));
    }
    // clean up
    pipelineManager.close();
}

