@Test
public void testSortDatanodes() throws Exception {
    List<String> nodes = new ArrayList();
    nodeManager.getAllNodes().stream().forEach(node -> nodes.add(node.getNetworkName()));
    // sort normal datanodes
    String client;
    client = nodes.get(0);
    List<DatanodeDetails> datanodeDetails = server.sortDatanodes(nodes, client);
    System.out.println("client = " + client);
    datanodeDetails.stream().forEach(node -> System.out.println(node.toString()));
    Assert.assertTrue(datanodeDetails.size() == nodeCount);
    // illegal client 1
    client += "X";
    datanodeDetails = server.sortDatanodes(nodes, client);
    System.out.println("client = " + client);
    datanodeDetails.stream().forEach(node -> System.out.println(node.toString()));
    Assert.assertTrue(datanodeDetails.size() == nodeCount);
    // illegal client 2
    client = "/default-rack";
    datanodeDetails = server.sortDatanodes(nodes, client);
    System.out.println("client = " + client);
    datanodeDetails.stream().forEach(node -> System.out.println(node.toString()));
    Assert.assertTrue(datanodeDetails.size() == nodeCount);
    // unknown node to sort
    nodes.add(UUID.randomUUID().toString());
    ScmBlockLocationProtocolProtos.SortDatanodesRequestProto request = ScmBlockLocationProtocolProtos.SortDatanodesRequestProto.newBuilder().addAllNodeNetworkName(nodes).setClient(client).build();
    ScmBlockLocationProtocolProtos.SortDatanodesResponseProto resp = service.sortDatanodes(request);
    Assert.assertTrue(resp.getNodeList().size() == nodeCount);
    System.out.println("client = " + client);
    resp.getNodeList().stream().forEach(node -> System.out.println(node.getNetworkName()));
    // all unknown nodes
    nodes.clear();
    nodes.add(UUID.randomUUID().toString());
    nodes.add(UUID.randomUUID().toString());
    nodes.add(UUID.randomUUID().toString());
    request = ScmBlockLocationProtocolProtos.SortDatanodesRequestProto.newBuilder().addAllNodeNetworkName(nodes).setClient(client).build();
    resp = service.sortDatanodes(request);
    System.out.println("client = " + client);
    Assert.assertTrue(resp.getNodeList().size() == 0);
    resp.getNodeList().stream().forEach(node -> System.out.println(node.getNetworkName()));
}

