@Test
public void testClone() {
    OmBucketInfo omBucketInfo = OmBucketInfo.newBuilder().setBucketName("bucket").setVolumeName("vol1").setCreationTime(Time.now()).setIsVersionEnabled(false).setStorageType(StorageType.ARCHIVE).setAcls(Collections.singletonList(new OzoneAcl(IAccessAuthorizer.ACLIdentityType.USER, "defaultUser", IAccessAuthorizer.ACLType.WRITE_ACL, OzoneAcl.AclScope.ACCESS))).build();
    /* Clone an omBucketInfo. */
    OmBucketInfo cloneBucketInfo = omBucketInfo.copyObject();
    Assert.assertEquals(omBucketInfo, cloneBucketInfo);
    /* Reset acl & check not equal. */
    omBucketInfo.setAcls(Collections.singletonList(new OzoneAcl(IAccessAuthorizer.ACLIdentityType.USER, "newUser", IAccessAuthorizer.ACLType.WRITE_ACL, OzoneAcl.AclScope.ACCESS)));
    Assert.assertNotEquals(omBucketInfo.getAcls().get(0), cloneBucketInfo.getAcls().get(0));
    /* Clone acl & check equal. */
    cloneBucketInfo = omBucketInfo.copyObject();
    Assert.assertEquals(omBucketInfo, cloneBucketInfo);
    Assert.assertEquals(omBucketInfo.getAcls().get(0), cloneBucketInfo.getAcls().get(0));
    /* Remove acl & check. */
    omBucketInfo.removeAcl(new OzoneAcl(IAccessAuthorizer.ACLIdentityType.USER, "newUser", IAccessAuthorizer.ACLType.WRITE_ACL, OzoneAcl.AclScope.ACCESS));
    Assert.assertEquals((int) 0, omBucketInfo.getAcls().size());
    Assert.assertEquals((int) 1, cloneBucketInfo.getAcls().size());
}

