@Test
public void testClone() throws Exception {
    String volumeName = "vol1";
    String admin = "admin";
    String owner = UserGroupInformation.getCurrentUser().getUserName();
    OmVolumeArgs omVolumeArgs = new OmVolumeArgs.Builder().setVolume(volumeName).setAdminName(admin).setCreationTime(Time.now()).setOwnerName(owner).setObjectID(1L).setUpdateID(1L).setQuotaInBytes(100L).addMetadata("key1", "value1").addMetadata("key2", "value2").addOzoneAcls(OzoneAcl.toProtobuf(new OzoneAcl(IAccessAuthorizer.ACLIdentityType.USER, "user1", IAccessAuthorizer.ACLType.READ, ACCESS))).build();
    OmVolumeArgs cloneVolumeArgs = omVolumeArgs.copyObject();
    Assert.assertEquals(omVolumeArgs, cloneVolumeArgs);
    // add user acl to write.
    omVolumeArgs.addAcl(new OzoneAcl(IAccessAuthorizer.ACLIdentityType.USER, "user1", IAccessAuthorizer.ACLType.WRITE, ACCESS));
    // Now check clone acl
    Assert.assertNotEquals(cloneVolumeArgs.getAclMap().getAcl().get(0), omVolumeArgs.getAclMap().getAcl().get(0));
    // Set user acl to Write_ACL.
    omVolumeArgs.setAcls(Collections.singletonList(new OzoneAcl(IAccessAuthorizer.ACLIdentityType.USER, "user1", IAccessAuthorizer.ACLType.WRITE_ACL, ACCESS)));
    Assert.assertNotEquals(cloneVolumeArgs.getAclMap().getAcl().get(0), omVolumeArgs.getAclMap().getAcl().get(0));
    // Now clone and check. It should have same as original acl.
    cloneVolumeArgs = (OmVolumeArgs) omVolumeArgs.copyObject();
    Assert.assertEquals(omVolumeArgs, cloneVolumeArgs);
    Assert.assertEquals(cloneVolumeArgs.getAclMap().getAcl().get(0), omVolumeArgs.getAclMap().getAcl().get(0));
    omVolumeArgs.removeAcl(new OzoneAcl(IAccessAuthorizer.ACLIdentityType.USER, "user1", IAccessAuthorizer.ACLType.WRITE_ACL, ACCESS));
    // Removing acl, in original omVolumeArgs it should have no acls.
    Assert.assertEquals(0, omVolumeArgs.getAclMap().getAcl().size());
    Assert.assertEquals(1, cloneVolumeArgs.getAclMap().getAcl().size());
}

@Test
public void testAddAcl() throws IOException {
    List<OzoneAcl> currentAcls = getDefaultAcls(new OzoneConfiguration());
    assertTrue(currentAcls.size() > 0);
    // Add new permission to existing acl entry.
    OzoneAcl oldAcl = currentAcls.get(0);
    OzoneAcl newAcl = new OzoneAcl(oldAcl.getType(), oldAcl.getName(), ACLType.READ_ACL, ACCESS);
    addAndVerifyAcl(currentAcls, newAcl, true, DEFAULT_ACLS.size());
    // Add same permission again and verify result
    addAndVerifyAcl(currentAcls, newAcl, false, DEFAULT_ACLS.size());
    // Add a new user acl entry.
    addAndVerifyAcl(currentAcls, USER1, true, DEFAULT_ACLS.size() + 1);
    // Add same acl entry again and verify result
    addAndVerifyAcl(currentAcls, USER1, false, DEFAULT_ACLS.size() + 1);
    // Add a new group acl entry.
    addAndVerifyAcl(currentAcls, GROUP1, true, DEFAULT_ACLS.size() + 2);
    // Add same acl entry again and verify result
    addAndVerifyAcl(currentAcls, GROUP1, false, DEFAULT_ACLS.size() + 2);
}

@Test
public void testRemoveAcl() {
    List<OzoneAcl> currentAcls = null;
    // add/remove to/from null OzoneAcls
    removeAndVerifyAcl(currentAcls, USER1, false, 0);
    addAndVerifyAcl(currentAcls, USER1, false, 0);
    removeAndVerifyAcl(currentAcls, USER1, false, 0);
    currentAcls = getDefaultAcls(new OzoneConfiguration());
    assertTrue(currentAcls.size() > 0);
    // Add new permission to existing acl entru.
    OzoneAcl oldAcl = currentAcls.get(0);
    OzoneAcl newAcl = new OzoneAcl(oldAcl.getType(), oldAcl.getName(), ACLType.READ_ACL, ACCESS);
    // Remove non existing acl entry
    removeAndVerifyAcl(currentAcls, USER1, false, DEFAULT_ACLS.size());
    // Remove non existing acl permission
    removeAndVerifyAcl(currentAcls, newAcl, false, DEFAULT_ACLS.size());
    // Add new permission to existing acl entry.
    addAndVerifyAcl(currentAcls, newAcl, true, DEFAULT_ACLS.size());
    // Remove the new permission added.
    removeAndVerifyAcl(currentAcls, newAcl, true, DEFAULT_ACLS.size());
    removeAndVerifyAcl(currentAcls, oldAcl, true, DEFAULT_ACLS.size() - 1);
}

