public void testCreateOzoneContainer() throws Exception {
    LOG.info("Test case: requireBlockToken: {} hasBlockToken: {} " + "blockTokenExpired: {}.", requireBlockToken, hasBlockToken, blockTokeExpired);
    conf.setBoolean(HddsConfigKeys.HDDS_BLOCK_TOKEN_ENABLED, requireBlockToken);
    long containerID = ContainerTestHelper.getTestContainerID();
    OzoneContainer container = null;
    System.out.println(System.getProperties().getProperty("java.library.path"));
    try {
        Pipeline pipeline = MockPipeline.createSingleNodePipeline();
        conf.set(HDDS_DATANODE_DIR_KEY, tempFolder.getRoot().getPath());
        conf.setInt(OzoneConfigKeys.DFS_CONTAINER_IPC_PORT, pipeline.getFirstNode().getPort(DatanodeDetails.Port.Name.STANDALONE).getValue());
        conf.setBoolean(OzoneConfigKeys.DFS_CONTAINER_IPC_RANDOM_PORT, false);
        DatanodeDetails dn = MockDatanodeDetails.randomDatanodeDetails();
        container = new OzoneContainer(dn, conf, getContext(dn), caClient);
        //Set scmId and manually start ozone container.
        container.start(UUID.randomUUID().toString());
        UserGroupInformation ugi = UserGroupInformation.createUserForTesting("user1", new String[] { "usergroup" });
        long expiryDate = (blockTokeExpired) ? Time.now() - 60 * 60 * 2 : Time.now() + 60 * 60 * 24;
        OzoneBlockTokenIdentifier tokenId = new OzoneBlockTokenIdentifier("testUser", "cid:lud:bcsid", EnumSet.allOf(AccessModeProto.class), expiryDate, "1234", 128L);
        int port = dn.getPort(DatanodeDetails.Port.Name.STANDALONE).getValue();
        if (port == 0) {
            port = secConfig.getConfiguration().getInt(OzoneConfigKeys.DFS_CONTAINER_IPC_PORT, DFS_CONTAINER_IPC_PORT_DEFAULT);
        }
        secretManager.start(caClient);
        Token<OzoneBlockTokenIdentifier> token = secretManager.generateToken("123", EnumSet.allOf(AccessModeProto.class), RandomUtils.nextLong());
        if (hasBlockToken) {
            ugi.addToken(token);
        }
        ugi.doAs((PrivilegedAction<Void>) () -> {
            try {
                XceiverClientGrpc client = new XceiverClientGrpc(pipeline, conf);
                client.connect(token.encodeToUrlString());
                if (hasBlockToken) {
                    createContainerForTesting(client, containerID, token);
                } else {
                    createContainerForTesting(client, containerID, null);
                }
            } catch (Exception e) {
                if (requireBlockToken && hasBlockToken && !blockTokeExpired) {
                    LOG.error("Unexpected error. ", e);
                    fail("Client with BlockToken should succeed when block token is" + " required.");
                }
                if (requireBlockToken && hasBlockToken && blockTokeExpired) {
                    assertTrue("Receive expected exception", e instanceof SCMSecurityException);
                }
                if (requireBlockToken && !hasBlockToken) {
                    assertTrue("Receive expected exception", e instanceof IOException);
                }
            }
            return null;
        });
    } finally {
        if (container != null) {
            container.stop();
        }
    }
}

