    // The old and new Leader OM NodeId must match since there was no new
    // election in the Ratis ring.
    Assert.assertEquals(leaderOMNodeId, newLeaderOMNodeId);
}

@Test
public void testOMRetryProxy() throws Exception {
    // Stop all the OMs.
    for (int i = 0; i < numOfOMs; i++) {
        cluster.stopOzoneManager(i);
    }
    final LogVerificationAppender appender = new LogVerificationAppender();
    final org.apache.log4j.Logger logger = Logger.getRootLogger();
    logger.addAppender(appender);
    try {
        createVolumeTest(true);
        // After making N (set maxRetries value) connection attempts to OMs,
        // the RpcClient should give up.
        fail("TestOMRetryProxy should fail when there are no OMs running");
    } catch (ConnectException e) {
        // Each retry attempt tries IPC_CLIENT_CONNECT_MAX_RETRIES times.
        // So there should be at least
        // OZONE_CLIENT_FAILOVER_MAX_ATTEMPTS * IPC_CLIENT_CONNECT_MAX_RETRIES
        // "Retrying connect to server" messages.
        // Also, the first call will result in EOFException.
        // That will result in another IPC_CLIENT_CONNECT_MAX_RETRIES attempts.
        Assert.assertEquals((OZONE_CLIENT_FAILOVER_MAX_ATTEMPTS + 1) * IPC_CLIENT_CONNECT_MAX_RETRIES, appender.countLinesWithMessage("Retrying connect to server:"));
        Assert.assertEquals(1, appender.countLinesWithMessage("Failed to connect to OMs:"));
        Assert.assertEquals(1, appender.countLinesWithMessage("Attempted " + OZONE_CLIENT_FAILOVER_MAX_ATTEMPTS + " failovers."));
    }
}

