/**
 * Verifies container placement metric.
 */
@Test(timeout = 60000)
public void test() throws IOException {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String value = "sample value";
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    volume.createBucket(bucketName);
    OzoneBucket bucket = volume.getBucket(bucketName);
    String keyName = UUID.randomUUID().toString();
    // Write data into a key
    try (OzoneOutputStream out = bucket.createKey(keyName, value.getBytes().length, ReplicationType.RATIS, THREE, new HashMap<>())) {
        out.write(value.getBytes());
    }
    // close container
    PipelineManager manager = cluster.getStorageContainerManager().getPipelineManager();
    List<Pipeline> pipelines = manager.getPipelines().stream().filter(p -> p.getType() == HddsProtos.ReplicationType.RATIS && p.getFactor() == HddsProtos.ReplicationFactor.THREE).collect(Collectors.toList());
    Pipeline targetPipeline = pipelines.get(0);
    List<DatanodeDetails> nodes = targetPipeline.getNodes();
    manager.finalizeAndDestroyPipeline(pipelines.get(0), true);
    // kill datanode to trigger under-replicated container replication
    cluster.shutdownHddsDatanode(nodes.get(0));
    try {
        Thread.sleep(5 * 1000);
    } catch (InterruptedException e) {
    }
    cluster.getStorageContainerManager().getReplicationManager().processContainersNow();
    try {
        Thread.sleep(30 * 1000);
    } catch (InterruptedException e) {
    }
    long totalRequest = getLongCounter("DatanodeRequestCount", metrics);
    long tryCount = getLongCounter("DatanodeChooseAttemptCount", metrics);
    long sucessCount = getLongCounter("DatanodeChooseSuccessCount", metrics);
    long compromiseCount = getLongCounter("DatanodeChooseFallbackCount", metrics);
    // Seems no under-replicated closed containers get replicated
    Assert.assertTrue(totalRequest == 0);
    Assert.assertTrue(tryCount == 0);
    Assert.assertTrue(sucessCount == 0);
    Assert.assertTrue(compromiseCount == 0);
}

