@Test
public void testAddToDBBatch() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    OmBucketInfo omBucketInfo = TestOMResponseUtils.createBucket(volumeName, bucketName);
    Assert.assertEquals(0, omMetadataManager.countRowsInTable(omMetadataManager.getBucketTable()));
    OMBucketCreateResponse omBucketCreateResponse = new OMBucketCreateResponse(OMResponse.newBuilder().setCmdType(OzoneManagerProtocolProtos.Type.CreateBucket).setStatus(OzoneManagerProtocolProtos.Status.OK).setCreateBucketResponse(CreateBucketResponse.newBuilder().build()).build(), omBucketInfo);
    omBucketCreateResponse.addToDBBatch(omMetadataManager, batchOperation);
    // Do manual commit and see whether addToBatch is successful or not.
    omMetadataManager.getStore().commitBatchOperation(batchOperation);
