    Assert.assertTrue(btIdentifier.getOmCertSerialId().equals(omCertSerialId));
    validateHash(token.getPassword(), btIdentifier.getBytes());
    tokenVerifier.verify("testUser", token.encodeToUrlString(), ContainerProtos.Type.PutBlock, "101");
    String notAllledBlockID = "NotAllowedBlockID";
    LambdaTestUtils.intercept(BlockTokenException.class, "Token for block ID: " + tokenBlockID + " can't be used to access block: " + notAllledBlockID, () -> tokenVerifier.verify("testUser", token.encodeToUrlString(), ContainerProtos.Type.PutBlock, notAllledBlockID));
